    static final int UPLEFT = 4, UPRIGHT = 5, DOWNLEFT = 6, DOWNRIGHT = 7;
    static int[] dx = {0, 0, -1, 1, -1, 1, -1, 1};
    static int[] dy = {1, -1, 0, 0, 1, 1, -1, -1};
    static final int MAX = 5 * 30 + 5;
    static boolean[][][][][] marked = new boolean[2 * MAX][2 * MAX][8][32][6];
    static Map<Pair, Boolean> mp = new HashMap<>();
    static int[] t = new int[100];

    static class Pair {
        int x, y;
        Pair(int x, int y) {
            this.x = x;
            this.y = y;
        }
        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (o == null || getClass() != o.getClass()) return false;
            Pair pair = (Pair) o;
            return x == pair.x && y == pair.y;
        }
        @Override
        public int hashCode() {
            return Objects.hash(x, y);
        }
    }

    static Pair rot(int dir) {
        if (dir == UP) return new Pair(UPLEFT, UPRIGHT);
        if (dir == DOWN) return new Pair(DOWNLEFT, DOWNRIGHT);
        if (dir == LEFT) return new Pair(UPLEFT, DOWNLEFT);
        if (dir == RIGHT) return new Pair(UPRIGHT, DOWNRIGHT);
        if (dir == UPLEFT) return new Pair(UP, LEFT);
        if (dir == UPRIGHT) return new Pair(UP, RIGHT);
        if (dir == DOWNLEFT) return new Pair(DOWN, LEFT);
        if (dir == DOWNRIGHT) return new Pair(DOWN, RIGHT);
        return null;
    }

